WITH daily_cum AS (SELECT wsit.web_site_id, td.t_time, ws.ws_net_profit, SUM(ws.ws_net_profit) OVER (PARTITION BY wsit.web_site_id ORDER BY td.t_time ROWS BETWEEN 7 PRECEDING AND CURRENT ROW) AS week_cum_profit FROM web_sales ws JOIN time_dim td ON ws.ws_sold_time_sk = td.t_time_sk JOIN web_site wsit ON ws.ws_web_site_sk = wsit.web_site_sk WHERE td.t_shift = 'Evening') SELECT web_site_id, t_time, ws_net_profit, week_cum_profit, CASE WHEN week_cum_profit > 80000 THEN 'Peak' ELSE 'Off-Peak' END AS demand_phase FROM daily_cum ORDER BY web_site_id, t_time
